  var restored=assign(base,teacher,"EO_DRAFT_GET",mapOf("draftId",d.get("id")));verify(studyfix.assignment.persistence.ExamBankRepository.compositionSelections(obj(restored.get("document")).get("examSelections")).equals(studyfix.assignment.persistence.ExamBankRepository.compositionSelections(selections)),"manual selection restored from SQLite");
  var changedDoc=new LinkedHashMap<>(obj(restored.get("document")));changedDoc.put("examSelections",List.of(selections.get(0),mapOf("versionId",second,"mode","MANUAL","count",2,"exerciseIds",List.of("EO_A","EO_C"))));var changed=assign(base,teacher,"EO_DRAFT_SAVE",mapOf("draftId",d.get("id"),"expectedRevision",restored.get("revision"),"document",changedDoc));verify(send(base,teacher,"EO_SCHEDULE",mapOf("draftId",d.get("id"),"expectedRevision",changed.get("revision"))).status()!=200,"changing exact selected ids with same count invalidates schedule");
  d=assign(base,teacher,"EO_DRAFT_SAVE",mapOf("draftId",d.get("id"),"expectedRevision",changed.get("revision"),"document",restored.get("document")));var scheduled=schedule(base,teacher,d);verify(number(scheduled,"problemCount",0)==2,"manual composition schedules exact subset");var clone=assign(base,teacher,"EO_CLONE",mapOf("contestId",scheduled.get("id")));verify(studyfix.assignment.persistence.ExamBankRepository.compositionSelections(obj(clone.get("document")).get("examSelections")).equals(studyfix.assignment.persistence.ExamBankRepository.compositionSelections(selections)),"cloning preserves exact manual ids including duplicated source choices");
